 auto fail=[&](const char*s){e=s;return false;};if(!p||n<160||n>1024*1024)return fail("Basement sprite size");if(std::memcmp(p,"ENCBANM1",8)||u32(p+8)!=1||u32(p+12)!=n||u32(p+20)!=1||u32(p+24)!=1||u32(p+28)!=6||u32(p+16)!=crc(p,n))return fail("Basement sprite header/version/CRC");for(size_t i=52;i<64;++i)if(p[i])return fail("Basement sprite reserved header");
