 if(end!=n||!count[0]||count[0]>65536||count[1]!=2||count[2]!=3||!count[3]||count[3]>1024||count[4]!=count[1]||count[5]!=1)return fail("Basement sprite counts/trailing data");const auto*s=p+offset[0];if(s[0]||s[count[0]-1]||!utf8(s,count[0]))return fail("Basement sprite UTF8");std::set<uint32_t>starts{0};for(uint32_t i=0;i+1<count[0];++i)if(!s[i])starts.insert(i+1);auto text=[&](uint32_t id,std::string&out){if(!starts.count(id))return false;out=std::string(reinterpret_cast<const char*>(s+id));return true;};
