 for(uint32_t i=0;i<count[1];++i){const auto*r=p+offset[1]+i*64;const auto*g=p+offset[4]+i*16;BasementActorResource a;a.id=u32(r);a.width=u32(r+12);a.height=u32(r+16);a.columns=u32(r+20);a.rows=u32(r+24);a.position={f32(g),f32(g+4)};a.offset={f32(g+8),f32(g+12)};std::copy(r+32,r+64,a.sha256.begin());if(!a.id||a.id==0xffffffff||!ids.insert(a.id).second||!text(u32(r+4),a.path)||!text(u32(r+8),a.source)||!path(a.path,"graphics/story/basement/",".t3x")||!path(a.source,"Graphics/",".png")||!a.width||!a.height||a.width>4096||a.height>4096||!a.columns||!a.rows||a.width%a.columns||a.height%a.rows||uint64_t(a.columns)*a.rows>65536||!text(u32(r+28),a.primary_path)||(!a.primary_path.empty()&&!path(a.primary_path,"graphics/actors/",".t3x"))||std::all_of(a.sha256.begin(),a.sha256.end(),[](uint8_t v){return!v;}))return fail("Basement sprite resource");for(uint32_t j=0;j<4;++j)if(!std::isfinite(f32(g+4*j))||std::abs(f32(g+4*j))>=1e6)return fail("Basement sprite transform");next.resources_.push_back(a);}
