uint32_t BasementActorData::frame(uint32_t id,double elapsed)const{const auto*a=animation(id);if(!valid_||!a||!std::isfinite(elapsed)||elapsed<0)return 0;uint32_t frame=a->keys.front().frame;for(const auto&k:a->keys){if(k.time>elapsed)break;frame=k.frame;}return frame;}
bool begin_basement_actor(const BasementActorData&d,uint32_t id,BasementActorPlayback&s,std::string&e){if(!d.valid()||!d.animation(id)){e="Unknown checked special actor animation";return false;}s={id,0,true};e.clear();return true;}
bool advance_basement_actor(const BasementActorData&d,double delta,BasementActorPlayback&s,std::string&e){if(!std::isfinite(delta)||delta<0||delta>double(.1f)){e="Special actor delta rejected";return false;}if(!s.visible){e.clear();return true;}const auto*a=d.animation(s.animation_id);if(!d.valid()||!a||!std::isfinite(s.elapsed)||s.elapsed<0){e="Special actor playback rejected";return false;}s.elapsed=std::min(double(a->length),s.elapsed+double(float(delta)));e.clear();return true;}
